    guy_patches = image_patch.find("guy")
    phone_patches = image_patch.find("phone")

    if not guy_patches or not phone_patches:
        return image_patch

    guy_patches.sort(key=lambda g: g.vertical_center)
    guy_on_top = guy_patches[-1]

    phone_patches.sort(key=lambda p: p.vertical_center)
    phone_on_bottom = phone_patches[0]

    if is_above(guy_on_top, phone_on_bottom):
        return guy_on_top
    else:
        return phone_on_bottom

def is_above(a: ImagePatch, b: ImagePatch) -> bool:
    return a.vertical_center < b.vertical_center

